mapper.select:
SELECT v.id, v.plate_number AS plateNumber, v.brand, v.seats, v.status, v.fuel_consumption AS fuelConsumption, v.route_id AS routeId, r.name AS routeName, v.driver_name AS driverName, v.driver_phone AS driverPhone, v.purchase_date AS purchaseDate, v.last_maintenance AS lastMaintenance, v.next_maintenance AS nextMaintenance, v.mileage, v.remark, v.create_time AS createTime FROM biz_vehicle v LEFT JOIN biz_route r ON v.route_id = r.id AND r.deleted = 0 WHERE v.deleted = 0
AND v.plate_number LIKE CONCAT('%', #{query.plateNumber}, '%')
AND v.status = #{query.status}
AND v.route_id = #{query.routeId}
AND v.brand LIKE CONCAT('%', #{query.brand}, '%')
ORDER BY v.create_time DESC
